import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { categories, createTasks } from './tasks.js';

const assets = new Map([
  ['/', ['index.html', 'text/html; charset=utf-8']],
  ['/style.css', ['style.css', 'text/css; charset=utf-8']],
  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']],
  ['/favicon.svg', ['favicon.svg', 'image/svg+xml']],
]);

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}

async function readJson(req) {
  if (req.headers['content-type']?.split(';')[0].trim() !== 'application/json') {
    throw Object.assign(new Error('JSON 형식으로 요청해 주세요.'), { status: 415 });
  }
  let length = 0;
  const chunks = [];
  for await (const chunk of req) {
    length += chunk.length;
    if (length > 8192) throw Object.assign(new Error('요청이 너무 큽니다.'), { status: 413 });
    chunks.push(chunk);
  }
  try {
    const value = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error();
    return value;
  } catch {
    throw Object.assign(new Error('올바른 JSON 객체가 필요합니다.'), { status: 400 });
  }
}

export function createApp(config) {
  let tasks = createTasks();
  const startedAt = new Date().toISOString();
  const server = createServer(async (req, res) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'");
    try {
      const { pathname } = new URL(req.url, 'http://localhost');
      if (req.method === 'GET' && pathname === '/healthz') {
        return json(res, 200, { status: 'ok', app: 'iris-demo-web', startedAt });
      }
      if (req.method === 'GET' && pathname === '/api/tasks') {
        return json(res, 200, { title: config.title, tasks });
      }
      if (req.method === 'POST' && pathname === '/api/tasks') {
        const body = await readJson(req);
        if (typeof body.title !== 'string' || !body.title.trim() || body.title.trim().length > 100) {
          return json(res, 400, { error: '할 일은 1~100자로 입력해 주세요.' });
        }
        if (!categories.includes(body.category)) return json(res, 400, { error: '분류를 확인해 주세요.' });
        if (tasks.length >= 100) return json(res, 409, { error: '최대 100개까지 저장할 수 있어요.' });
        const task = { id: randomUUID(), title: body.title.trim(), category: body.category, done: false };
        tasks.unshift(task);
        return json(res, 201, { task });
      }
      const taskRoute = pathname.match(/^\/api\/tasks\/([a-z0-9-]+)$/);
      if (taskRoute && ['PATCH', 'DELETE'].includes(req.method)) {
        const task = tasks.find(item => item.id === taskRoute[1]);
        if (!task) return json(res, 404, { error: '할 일을 찾을 수 없어요.' });
        if (req.method === 'DELETE') {
          tasks = tasks.filter(item => item.id !== task.id);
          res.writeHead(204);
          return res.end();
        }
        const body = await readJson(req);
        if (typeof body.done !== 'boolean') return json(res, 400, { error: '완료 상태는 boolean이어야 합니다.' });
        task.done = body.done;
        return json(res, 200, { task });
      }
      if (req.method === 'GET' && assets.has(pathname)) {
        const [file, type] = assets.get(pathname);
        const content = await readFile(new URL('../public/' + file, import.meta.url));
        res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-cache' });
        return res.end(content);
      }
      json(res, 404, { error: '페이지를 찾을 수 없어요.' });
    } catch (error) {
      if (!error.status) console.error('[request-error]', error.stack);
      if (!res.headersSent && !res.destroyed) json(res, error.status || 500, { error: error.status ? error.message : '서버에서 오류가 발생했어요.' });
    }
  });
  server.requestTimeout = 10000;
  return server;
}

export function loadConfig(env = process.env) {
  const port = Number(env.PORT ?? 3000);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error('Invalid configuration: PORT must be an integer between 1 and 65535');
  }
  return {
    port,
    host: env.HOST || '0.0.0.0',
    title: env.APP_TITLE?.trim() || '작은 완료',
  };
}

import { loadConfig } from './config.js';
import { createApp } from './app.js';

try {
  const config = loadConfig();
  const server = createApp(config);
  server.on('error', error => {
    console.error(new Date().toISOString(), '[startup-error]', error.stack);
    process.exitCode = 1;
  });
  server.listen(config.port, config.host, () => {
    console.log(new Date().toISOString(), '[ready]', `IRIS demo listening on ${config.host}:${config.port}`);
  });
  for (const signal of ['SIGINT', 'SIGTERM']) {
    process.once(signal, () => {
      console.log(new Date().toISOString(), '[shutdown]', signal);
      server.close(() => process.exit(0));
      setTimeout(() => process.exit(1), 5000).unref();
    });
  }
} catch (error) {
  console.error(new Date().toISOString(), '[startup-error]', error.stack);
  process.exitCode = 1;
}

import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';

export const categories = ['개발', '확인', '아이디어'];

export function createTasks() {
  const file = new URL('../data/tasks.json', import.meta.url);
  const initialTasks = JSON.parse(readFileSync(file, 'utf8'));
  return initialTasks.map(task => ({ id: randomUUID(), ...task }));
}

const $ = selector => document.querySelector(selector);
let tasks = [];
let filter = 'all';
let busy = false;

$('#today').textContent = new Intl.DateTimeFormat('ko-KR', { month: 'long', day: 'numeric', weekday: 'long' }).format(new Date());

async function request(path, options = {}) {
  const response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...options.headers } });
  if (response.status === 204) return;
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || '요청을 처리하지 못했어요.');
  return result;
}

function message(text, error = false) {
  $('#message').textContent = text;
  $('#message').classList.toggle('error', error);
}

function render() {
  const done = tasks.filter(task => task.done).length;
  const active = tasks.length - done;
  const percent = tasks.length ? Math.round(done / tasks.length * 100) : 0;
  for (const [id, value] of Object.entries({ 'total-badge': tasks.length, 'all-count': tasks.length, 'active-count': active, 'done-count': done, 'stat-total': tasks.length, 'stat-active': active, 'stat-done': done, 'progress-number': percent })) {
    document.getElementById(id).textContent = value;
  }
  $('#progress').value = percent;
  $('#progress-message').textContent = tasks.length ? `${tasks.length}개 중 ${done}개 완료했어요. ${active ? '좋은 흐름이에요!' : '모두 끝냈어요!'}` : '첫 번째 할 일부터 시작해 볼까요?';
  const visible = tasks.filter(task => filter === 'all' || (filter === 'done' ? task.done : !task.done));
  $('#task-list').replaceChildren();
  for (const task of visible) {
    const row = document.createElement('li');
    row.className = `task${task.done ? ' done' : ''}`;
    const label = document.createElement('label');
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.done;
    checkbox.disabled = busy;
    checkbox.addEventListener('change', () => mutate(async () => {
      const result = await request(`/api/tasks/${task.id}`, { method: 'PATCH', body: JSON.stringify({ done: checkbox.checked }) });
      tasks = tasks.map(item => item.id === task.id ? result.task : item);
    }, checkbox.checked ? '하나 더 완료했어요. 잘했어요!' : '다시 진행 중으로 옮겼어요.'));
    const name = document.createElement('span');
    name.className = 'task-name';
    name.textContent = task.title;
    label.append(checkbox, name);
    const category = document.createElement('span');
    category.className = 'category';
    category.dataset.category = task.category;
    category.textContent = task.category;
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete';
    remove.textContent = '×';
    remove.disabled = busy;
    remove.setAttribute('aria-label', `${task.title} 삭제`);
    remove.addEventListener('click', () => mutate(async () => {
      await request(`/api/tasks/${task.id}`, { method: 'DELETE' });
      tasks = tasks.filter(item => item.id !== task.id);
    }, '할 일을 삭제했어요.'));
    row.append(label, category, remove);
    $('#task-list').append(row);
  }
  $('#empty-state').hidden = visible.length > 0;
  $('#empty-state h3').textContent = filter === 'done' ? '완료한 할 일이 아직 없어요' : filter === 'active' && tasks.length ? '모든 할 일을 끝냈어요!' : '아직 할 일이 없어요';
  $('#empty-state p').textContent = filter === 'done' ? '할 일 옆 체크박스를 눌러 완료해 보세요.' : '위에서 새로운 할 일을 추가해 보세요.';
}

async function mutate(action, success) {
  if (busy) return;
  busy = true;
  $('#task-form button').disabled = true;
  render();
  try {
    await action();
    message(success);
  } catch (error) {
    message(error.message === 'Failed to fetch' ? '서버에 연결할 수 없어요. 잠시 후 다시 시도해 주세요.' : error.message, true);
  } finally {
    busy = false;
    $('#task-form button').disabled = false;
    render();
  }
}

$('#task-form').addEventListener('submit', event => {
  event.preventDefault();
  const title = $('#task-input').value.trim();
  const category = $('#task-category').value;
  if (!title) return message('할 일을 입력해 주세요.', true);
  mutate(async () => {
    const result = await request('/api/tasks', { method: 'POST', body: JSON.stringify({ title, category }) });
    tasks.unshift(result.task);
    $('#task-input').value = '';
    $('#task-input').focus();
  }, '새로운 할 일을 추가했어요.');
});

for (const button of document.querySelectorAll('[data-filter]')) {
  button.addEventListener('click', () => {
    filter = button.dataset.filter;
    for (const item of document.querySelectorAll('[data-filter]')) item.setAttribute('aria-pressed', item === button ? 'true' : 'false');
    render();
  });
}

try {
  const data = await request('/api/tasks');
  tasks = data.tasks;
  $('#app-title').textContent = data.title;
  document.title = `${data.title} · IRIS`;
  $('#connection').textContent = '서버 연결됨';
  $('#connection').classList.add('online');
  render();
} catch {
  $('#connection').textContent = '연결 실패';
  $('#connection').classList.add('offline');
  $('#task-form button').disabled = true;
  message('할 일을 불러오지 못했어요. 서버를 확인한 뒤 새로고침해 주세요.', true);
}

